CREATE OR REPLACE FUNCTION private.gridex_guard_site_resolution_materialization_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_resolution public.customer_site_resolution%rowtype;
  v_price_safe boolean := false;
  v_coordinates jsonb;
  v_canonical_status boolean := false;
begin
  if new.resolution_id is not distinct from old.resolution_id then
    v_canonical_status := lower(coalesce(new.resolution_status, '')) in (
      'grid_area_master_validated',
      'facility_data_requested',
      'facility_data_received',
      'facility_verified'
    );

    if v_canonical_status and (
      new.grid_owner_id is distinct from old.grid_owner_id
      or new.grid_area_code is distinct from old.grid_area_code
      or new.price_area_code is distinct from old.price_area_code
      or new.latitude is distinct from old.latitude
      or new.longitude is distinct from old.longitude
      or new.sweref99_x is distinct from old.sweref99_x
      or new.sweref99_y is distinct from old.sweref99_y
    ) then
      raise exception using
        errcode = '23514',
        message = 'canonical_site_geography_requires_resolution_binding';
    end if;
    return new;
  end if;

  if new.resolution_id is null then
    new.grid_owner_id := null;
    new.grid_area_code := null;
    new.price_area_code := null;
    new.latitude := null;
    new.longitude := null;
    new.sweref99_x := null;
    new.sweref99_y := null;
    return new;
  end if;

  select *
    into v_resolution
    from public.customer_site_resolution
   where id = new.resolution_id
     and company_id = new.company_id
     and customer_site_id = new.id;

  if not found then
    raise exception using
      errcode = '23514',
      message = 'customer_site_resolution binding must match company and site';
  end if;

  v_price_safe :=
    v_resolution.price_area in ('SE1', 'SE2', 'SE3', 'SE4')
    and v_resolution.price_area_unique_count = 1
    and (
      v_resolution.price_area_assurance_status = 'verified'
      or (
        v_resolution.price_area_assurance_status = 'estimated'
        and v_resolution.price_area_assurance_confidence >= 0.8
      )
    );

  new.price_area_code := case when v_price_safe then v_resolution.price_area else null end;

  if lower(coalesce(v_resolution.resolution_status, '')) = 'postal_suggested' then
    new.grid_owner_id := null;
    new.grid_area_code := null;
  else
    new.grid_owner_id := v_resolution.grid_owner_id;
    new.grid_area_code := v_resolution.grid_area_code;
  end if;

  v_coordinates := coalesce(v_resolution.result_snapshot->'coordinates', '{}'::jsonb);
  new.latitude := nullif(v_coordinates->>'latitude', '')::numeric;
  new.longitude := nullif(v_coordinates->>'longitude', '')::numeric;
  new.sweref99_x := nullif(v_coordinates->>'sweref99X', '')::numeric;
  new.sweref99_y := nullif(v_coordinates->>'sweref99Y', '')::numeric;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.gridex_learn_verified_postal_mapping_from_site_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_postal_code text;
  v_city text;
  v_grid_area_code text;
  v_price_area text;
  v_now timestamptz := now();
begin
  if lower(coalesce(new.resolution_status, '')) not in ('facility_verified', 'manual_verified') then
    return new;
  end if;

  v_postal_code := regexp_replace(coalesce(new.postal_code, ''), '[^0-9]', '', 'g');
  v_city := nullif(btrim(new.city), '');
  v_grid_area_code := nullif(upper(regexp_replace(coalesce(new.grid_area_code, ''), '\s+', '', 'g')), '');
  v_price_area := nullif(upper(btrim(new.price_area_code)), '');

  if v_postal_code !~ '^[0-9]{5}$'
     or v_grid_area_code is null
     or v_price_area not in ('SE1', 'SE2', 'SE3', 'SE4') then
    return new;
  end if;

  update public.platform_postal_code_grid_mappings
     set price_area = v_price_area,
         confidence = 1.0,
         is_active = true,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'learned_from', 'verified_customer_site',
           'verification_count', coalesce(nullif(metadata->>'verification_count', '')::integer, 0) + 1,
           'last_verified_at', v_now
         ),
         updated_at = v_now
   where postal_code = v_postal_code
     and coalesce(lower(city), '') = coalesce(lower(v_city), '')
     and coalesce(upper(grid_area_code), '') = v_grid_area_code
     and source = 'verified_customer_site';

  if not found then
    insert into public.platform_postal_code_grid_mappings (
      postal_code,
      city,
      grid_area_code,
      price_area,
      confidence,
      source,
      is_active,
      metadata,
      created_at,
      updated_at
    ) values (
      v_postal_code,
      v_city,
      v_grid_area_code,
      v_price_area,
      1.0,
      'verified_customer_site',
      true,
      jsonb_build_object(
        'learned_from', 'verified_customer_site',
        'verification_count', 1,
        'first_verified_at', v_now,
        'last_verified_at', v_now
      ),
      v_now,
      v_now
    )
    on conflict do nothing;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.gridex_select_provisional_grid_owner_from_unique_postal_city_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_resolution jsonb;
  v_assurance jsonb;
  v_evidence jsonb;
  v_postal_code text;
  v_city text;
  v_evidence_city text;
  v_evidence_grid_area_code text;
  v_mapping_count integer := 0;
  v_distinct_grid_area_count integer := 0;
  v_distinct_price_area_count integer := 0;
  v_grid_area_code text;
  v_grid_area_name text;
  v_price_area text;
  v_ops_grid_owner_id uuid;
  v_grid_owner_name text;
  v_mapping_confidence numeric;
begin
  if new.grid_owner_id is not null
     or new.selected_grid_owner_id is not null
     or coalesce(new.is_active, true) is not true
     or nullif(btrim(coalesce(new.address_hash, '')), '') is null then
    return new;
  end if;

  v_resolution := coalesce(new.metadata, '{}'::jsonb) -> 'energy_resolution';
  if jsonb_typeof(v_resolution) <> 'object' then return new; end if;

  v_assurance := v_resolution -> 'priceAreaAssurance';
  v_evidence := v_assurance -> 'evidence';
  if jsonb_typeof(v_assurance) <> 'object'
     or jsonb_typeof(v_evidence) <> 'object'
     or v_assurance ->> 'source' <> 'postal_city_consensus'
     or v_evidence ->> 'city_scope' <> 'exact_city'
     or v_assurance ->> 'candidateCount' <> '1'
     or v_assurance ->> 'uniquePriceAreaCount' <> '1'
     or v_evidence ->> 'candidate_count' <> '1'
     or coalesce(v_evidence ->> 'mapping_conflict_count', '0') <> '0'
     or coalesce(v_evidence ->> 'unknown_candidate_count', '0') <> '0'
     or coalesce(v_evidence ->> 'candidate_limit_exceeded', 'false') <> 'false'
     or jsonb_typeof(v_evidence -> 'grid_area_codes') <> 'array'
     or jsonb_array_length(v_evidence -> 'grid_area_codes') <> 1 then
    return new;
  end if;

  if coalesce(v_assurance ->> 'confidence', '') !~ '^[0-9]+([.][0-9]+)?$'
     or (v_assurance ->> 'confidence')::numeric < 0.8 then
    return new;
  end if;

  v_postal_code := regexp_replace(coalesce(new.postal_code, ''), '[^0-9]', '', 'g');
  v_city := lower(regexp_replace(btrim(coalesce(new.city, '')), '\s+', ' ', 'g'));
  v_evidence_city := lower(regexp_replace(btrim(coalesce(v_evidence ->> 'requested_city', '')), '\s+', ' ', 'g'));
  v_evidence_grid_area_code := upper(regexp_replace(coalesce(v_evidence -> 'grid_area_codes' ->> 0, ''), '\s+', '', 'g'));

  if v_postal_code !~ '^[0-9]{5}$'
     or v_city = ''
     or regexp_replace(coalesce(v_evidence ->> 'postal_code', ''), '[^0-9]', '', 'g') <> v_postal_code
     or v_evidence_city <> v_city
     or v_evidence_grid_area_code = '' then
    return new;
  end if;

  select count(*)::integer,
         count(distinct upper(regexp_replace(coalesce(m.grid_area_code, ''), '\s+', '', 'g')))::integer,
         count(distinct upper(coalesce(m.price_area, '')))::integer
    into v_mapping_count, v_distinct_grid_area_count, v_distinct_price_area_count
  from public.platform_postal_code_grid_mappings m
  where m.is_active = true
    and regexp_replace(coalesce(m.postal_code, ''), '[^0-9]', '', 'g') = v_postal_code
    and lower(regexp_replace(btrim(coalesce(m.city, '')), '\s+', ' ', 'g')) = v_city;

  if v_mapping_count <> 1
     or v_distinct_grid_area_count <> 1
     or v_distinct_price_area_count <> 1 then
    return new;
  end if;

  select upper(regexp_replace(m.grid_area_code, '\s+', '', 'g')),
         ga.grid_area_name,
         upper(m.price_area),
         pgo.ops_grid_owner_id,
         pgo.name,
         m.confidence
    into v_grid_area_code, v_grid_area_name, v_price_area,
         v_ops_grid_owner_id, v_grid_owner_name, v_mapping_confidence
  from public.platform_postal_code_grid_mappings m
  join public.platform_grid_areas ga
    on upper(regexp_replace(ga.grid_area_code, '\s+', '', 'g')) = upper(regexp_replace(m.grid_area_code, '\s+', '', 'g'))
   and ga.is_active = true
  join public.platform_grid_owners pgo on pgo.id = ga.grid_owner_id
  where m.is_active = true
    and regexp_replace(coalesce(m.postal_code, ''), '[^0-9]', '', 'g') = v_postal_code
    and lower(regexp_replace(btrim(coalesce(m.city, '')), '\s+', ' ', 'g')) = v_city
  limit 1;

  if v_grid_area_code is null
     or v_ops_grid_owner_id is null
     or coalesce(v_mapping_confidence, 0) < 0.8
     or v_grid_area_code <> v_evidence_grid_area_code
     or upper(coalesce(v_resolution ->> 'priceArea', v_price_area)) <> upper(v_price_area)
     or (new.price_area_code is not null and upper(new.price_area_code) <> upper(v_price_area)) then
    return new;
  end if;

  new.selected_grid_owner_id := v_ops_grid_owner_id;
  new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
    'provisional_grid_owner_selection',
    jsonb_build_object(
      'source', 'unique_postal_city_masterdata',
      'canonical', false,
      'postal_code', v_postal_code,
      'city', new.city,
      'grid_area_code_candidate', v_grid_area_code,
      'grid_area_name_candidate', v_grid_area_name,
      'grid_owner_id', v_ops_grid_owner_id,
      'grid_owner_name', v_grid_owner_name,
      'price_area', v_price_area,
      'confidence', v_mapping_confidence,
      'selected_at', now(),
      'purpose', 'facility_information_routing'
    )
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.canonical_enforce_company_ediel_projection_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_state public.ediel_production_state%rowtype;
  v_projection_status text;
begin
  select * into v_state
    from public.ediel_production_state
   where company_id = new.id;

  if not found then
    return new;
  end if;

  v_projection_status := case v_state.state
    when 'live' then 'live'
    when 'paused' then 'paused'
    when 'blocked' then 'blocked'
    when 'prepared' then 'production_prepared'
    when 'retired' then 'blocked'
    when 'configuring' then 'not_ready'
    when 'disabled' then 'not_ready'
    else 'not_ready'
  end;

  new.production_status := v_projection_status;
  new.ediel_production_status := v_projection_status;
  new.live_ediel_enabled := v_state.state = 'live';
  new.ediel_production_enabled := v_state.state = 'live';

  if v_state.state = 'live' then
    new.operating_environment := 'production';
    new.live_blocked_reason := null;
  elsif v_state.state = 'prepared' then
    new.live_blocked_reason := null;
  elsif v_state.state = 'blocked' then
    new.live_blocked_reason := v_state.blocked_reason;
  elsif v_state.state = 'paused' then
    new.live_blocked_reason := coalesce(v_state.pause_reason, v_state.blocked_reason);
  elsif v_state.state = 'retired' then
    new.live_blocked_reason := coalesce(v_state.blocked_reason, 'ediel_production_retired');
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_customer_invoice_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if tg_op = 'UPDATE'
     and new.company_id is not distinct from old.company_id
     and new.id is not distinct from old.id then
    new.invoice_reference := old.invoice_reference;
    return new;
  end if;
  new.invoice_reference := 'invoice_' || substr(
    translate(
      rtrim(encode(extensions.digest(convert_to(
        'gridex-public-reference:v1:' || new.company_id::text || ':invoice:' || new.id::text,
        'UTF8'
      ), 'sha256'::text), 'base64'), '='),
      '+/', '-_'
    ),
    1,
    32
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_apply_contract_offer_standard_fees()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_offer public.contract_offers%rowtype;
begin
  if new.contract_offer_id is null or new.company_id is null then
    return new;
  end if;

  -- Customer-specific/manual pricing is intentional and must not be replaced
  -- by catalog values merely because the original offer reference is retained.
  if coalesce(new.source_type, '') in ('manual', 'manual_override') then
    return new;
  end if;

  select offer.*
    into v_offer
  from public.contract_offers offer
  where offer.id = new.contract_offer_id
    and offer.company_id = new.company_id;

  if not found then
    return new;
  end if;

  new.monthly_fee_sek := v_offer.monthly_fee_sek;
  new.invoice_fee_sek := v_offer.invoice_fee_sek;
  new.green_fee_mode := v_offer.green_fee_mode;
  new.green_fee_value := v_offer.green_fee_value;
  new.discount_value := v_offer.discount_value;
  new.discount_unit := v_offer.discount_unit;
  new.start_fee_sek := v_offer.start_fee_sek;
  new.admin_fee_sek := v_offer.admin_fee_sek;
  new.break_fee_sek := v_offer.break_fee_sek;
  new.vat_rate := v_offer.vat_rate;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_company_status text;
begin
  if new.company_id is null then
    return new;
  end if;

  select status into v_company_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_company_status, 'active') not in ('active', 'onboarding') then
    raise exception 'Tenant % is %, write is blocked for operational data', new.company_id, v_company_status
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_role_scope_is_consistent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_is_platform boolean;
begin
  select public.gridex_normalize_platform_role(coalesce(r.key, r.name))
           in ('super_admin', 'platform_admin')
    into v_is_platform
  from public.roles r
  where r.id = new.role_id;

  if v_is_platform is null then
    return new;
  end if;

  if v_is_platform and new.company_id is not null then
    raise exception 'platform_role_must_be_global'
      using errcode = '23514',
            detail = 'A super_admin or platform_admin role cannot be scoped to a company.';
  end if;

  if not v_is_platform and new.company_id is null then
    raise exception 'company_role_requires_company'
      using errcode = '23514',
            detail = 'A non-platform role must be bound to a company; a global company role grants everywhere.';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_assign_customer_contract_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.customer_id is null or new.company_id is null then return new; end if;
  if nullif(btrim(new.customer_number),'') is null then
    select c.customer_number into new.customer_number from public.customers c where c.id=new.customer_id and c.company_id=new.company_id;
  end if;
  if nullif(btrim(new.customer_number),'') is null then raise exception using errcode='23502',message='customer_contract_customer_number_required'; end if;
  if nullif(btrim(new.contract_number),'') is null then new.contract_number := public.gridex_next_contract_number(new.company_id,new.customer_number); end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_assign_customer_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.customer_number is null or btrim(new.customer_number) = '' then
    new.customer_number := public.gridex_next_customer_number(new.company_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_admin_users_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  insert into public.admin_users_audit_events(admin_user_id, action, actor_user_id, old_row, new_row)
  values (
    case
      when tg_op = 'INSERT' then coalesce(to_jsonb(new)->>'id', to_jsonb(new)->>'user_id')
      when tg_op = 'UPDATE' then coalesce(to_jsonb(new)->>'id', to_jsonb(old)->>'id', to_jsonb(new)->>'user_id', to_jsonb(old)->>'user_id')
      else coalesce(to_jsonb(old)->>'id', to_jsonb(old)->>'user_id')
    end,
    tg_op,
    auth.uid(),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_critical_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
      declare
        v_old jsonb := case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) else null end;
        v_new jsonb := case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) else null end;
        v_company_id uuid := null;
        v_actor uuid := null;
        v_entity_id text := null;
      begin
        if TG_TABLE_NAME = 'audit_logs' then
          return coalesce(NEW, OLD);
        end if;

        v_company_id := nullif(coalesce(v_new ->> 'company_id', v_old ->> 'company_id'), '')::uuid;
        if v_company_id is null and TG_TABLE_NAME = 'companies' then
          v_company_id := nullif(coalesce(v_new ->> 'id', v_old ->> 'id'), '')::uuid;
        end if;

        v_actor := nullif(coalesce(
          v_new ->> 'updated_by',
          v_new ->> 'created_by',
          v_new ->> 'actor_user_id',
          v_new ->> 'invited_by',
          v_new ->> 'paused_by',
          v_old ->> 'updated_by',
          v_old ->> 'created_by',
          v_old ->> 'actor_user_id',
          v_old ->> 'invited_by',
          v_old ->> 'paused_by'
        ), '')::uuid;

        v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');

        insert into public.audit_logs (
          company_id,
          actor_user_id,
          entity_type,
          entity_id,
          action,
          old_values,
          new_values,
          metadata
        ) values (
          v_company_id,
          v_actor,
          TG_TABLE_NAME,
          v_entity_id,
          lower(TG_TABLE_NAME || '_' || TG_OP),
          v_old,
          v_new,
          jsonb_build_object(
            'source', 'gridex_audit_critical_row_change',
            'operation', TG_OP,
            'table', TG_TABLE_NAME
          )
        );

        return coalesce(NEW, OLD);
      end;
      $function$

CREATE OR REPLACE FUNCTION public.gridex_billing_underlays_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_company_id uuid;
begin
  if new.customer_id is not null and to_regclass('public.customers') is not null then
    select company_id into parent_company_id from public.customers where id = new.customer_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_id');
  end if;
  if new.customer_contract_id is not null and to_regclass('public.customer_contracts') is not null then
    select company_id into parent_company_id from public.customer_contracts where id = new.customer_contract_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_contract_id');
  elsif new.contract_id is not null and to_regclass('public.customer_contracts') is not null then
    select company_id into parent_company_id from public.customer_contracts where id = new.contract_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'contract_id');
  end if;
  if new.site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'site_id');
  end if;
  if new.metering_point_id is not null and to_regclass('public.metering_points') is not null then
    select company_id into parent_company_id from public.metering_points where id = new.metering_point_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'metering_point_id');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_contract_snapshot_to_quote_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_snapshot jsonb:=coalesce(new.snapshot_json,'{}'::jsonb);
  v_quote public.website_contract_quotes%rowtype;
  v_requires_quote boolean;
begin
  new.snapshot_schema_version:=coalesce(
    new.snapshot_schema_version,
    v_snapshot->>'snapshot_schema',
    v_snapshot->>'schema_version'
  );

  if new.snapshot_schema_version is distinct from 'gridex_contract_pricing_v6_selection' then
    return new;
  end if;

  new.quote_reference:=coalesce(
    new.quote_reference,v_snapshot->>'quote_reference'
  );
  new.quote_hash:=coalesce(new.quote_hash,v_snapshot->>'quote_hash');
  new.price_option_reference:=coalesce(
    new.price_option_reference,v_snapshot->>'price_option_reference'
  );
  new.area_price_reference:=coalesce(
    new.area_price_reference,v_snapshot->>'area_price_reference'
  );
  new.invoice_delivery_method:=coalesce(
    new.invoice_delivery_method,v_snapshot->>'invoice_delivery_method'
  );
  if new.selected_component_references='{}'::text[] then
    new.selected_component_references:=array(
      select value
      from jsonb_array_elements_text(
        coalesce(v_snapshot->'selected_component_references','[]'::jsonb)
      )
    );
  end if;
  v_requires_quote:=coalesce(new.source,'') in (
    'website_customer_applications',
    'external_website',
    'website_application'
  );
  if (v_requires_quote and new.quote_reference is null)
    or (v_requires_quote and new.quote_hash is null)
    or new.price_option_reference is null
    or new.invoice_delivery_method is null
    or (
      v_snapshot->>'contract_type'='fixed'
      and new.area_price_reference is null
    )
    or jsonb_typeof(new.base_price_components_snapshot)<>'array'
    or jsonb_typeof(new.price_components_snapshot)<>'array' then
    raise exception using
      errcode='23514',
      message='contract_commercial_snapshot_identity_incomplete';
  end if;

  if v_requires_quote then
    select quote.*
      into v_quote
    from public.website_contract_quotes quote
    where quote.company_id=new.company_id
      and quote.quote_reference=new.quote_reference;
    if not found
      or v_quote.quote_hash is distinct from new.quote_hash
      or v_quote.price_option_reference
        is distinct from new.price_option_reference
      or v_quote.area_price_reference is distinct from new.area_price_reference
      or v_quote.invoice_delivery_method
        is distinct from new.invoice_delivery_method
      or v_quote.selected_component_references
        is distinct from new.selected_component_references
      or v_quote.resolved_base_components
        is distinct from new.base_price_components_snapshot
      or v_quote.resolved_price_components
        is distinct from new.price_components_snapshot then
      raise exception using
        errcode='23514',
        message='contract_snapshot_quote_selection_mismatch';
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_customer_contract_to_exact_publication()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v public.contract_publication_versions;
  pv public.contract_product_versions;
begin
  if new.contract_publication_version_id is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    join public.contract_publications publication
      on publication.id = cpv.contract_publication_id
    join public.tenant_contract_assignments assignment
      on assignment.id = publication.assignment_id
    where cpv.id = new.contract_publication_version_id
      and assignment.company_id = new.company_id
      and assignment.status = 'active'
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and (new.offer_reference is null or new.offer_reference = cpv.offer_reference)
    limit 1;
  elsif new.public_contract_offer_id is not null or new.offer_reference is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    where cpv.offer_reference = new.offer_reference
      and cpv.legacy_public_contract_offer_id = new.public_contract_offer_id
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and exists (
        select 1
        from public.public_contract_offers offer
        where offer.id = cpv.legacy_public_contract_offer_id
          and offer.company_id = new.company_id
      )
    limit 1;
  else
    return new;
  end if;

  if not found then
    raise exception using errcode='23514', message='exact_published_contract_version_required';
  end if;

  select *
  into pv
  from public.contract_product_versions
  where id = v.contract_product_version_id
    and locked_at is not null
    and status = 'approved';
  if not found then
    raise exception using errcode='23514', message='exact_approved_contract_product_version_required';
  end if;

  new.offer_reference := v.offer_reference;
  new.contract_publication_version_id := v.id;
  new.contract_product_version_id := pv.id;
  new.contract_product_id := pv.contract_product_id;
  new.legal_bundle_version_id := v.legal_bundle_version_id;
  new.price_plan_id := v.price_plan_id;
  new.price_plan_version_id := v.price_plan_version_id;
  new.price_book_id := v.price_book_id;
  new.commercial_snapshot := coalesce(
    v.publication_snapshot->'commercial_snapshot',
    pv.commercial_snapshot,
    '{}'::jsonb
  );
  new.legal_snapshot := coalesce(
    v.publication_snapshot->'legal_snapshot',
    (select rendered_snapshot from public.legal_bundle_versions where id = v.legal_bundle_version_id),
    '{}'::jsonb
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_bind_internal_customer_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_publication_id uuid; v_publication public.contract_publication_versions%rowtype;
  v_product public.contract_product_versions%rowtype;
begin
  if new.contract_offer_id is null or new.contract_publication_version_id is not null then return new; end if;
  v_publication_id:=public.gridex_ensure_internal_contract_publication(new.company_id,new.contract_offer_id,coalesce(new.created_by,new.updated_by));
  select * into v_publication from public.contract_publication_versions where id=v_publication_id;
  select * into v_product from public.contract_product_versions where id=v_publication.contract_product_version_id;
  new.contract_publication_version_id:=v_publication.id;
  new.contract_product_version_id:=v_product.id;
  new.contract_product_id:=v_product.contract_product_id;
  new.legal_bundle_version_id:=v_publication.legal_bundle_version_id;
  new.price_plan_id:=v_publication.price_plan_id;
  new.price_plan_version_id:=v_publication.price_plan_version_id;
  new.price_book_id:=v_publication.price_book_id;
  new.offer_reference:=coalesce(new.offer_reference,v_publication.offer_reference);
  new.commercial_snapshot:=v_product.commercial_snapshot;
  new.legal_snapshot:=(select rendered_snapshot from public.legal_bundle_versions where id=v_publication.legal_bundle_version_id);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_block_contract_price_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Escape hatch for explicit DBA maintenance (GDPR erasure, data repair):
  --   set local app.gridex_pricing_maintenance = 'on';
  if coalesce(current_setting('app.gridex_pricing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  raise exception 'contract_price_snapshots are immutable (%). Create a new snapshot instead of mutating an existing one.', tg_op
    using errcode = 'P0001';
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_canonicalize_company_org_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.org_number := coalesce(nullif(btrim(new.org_number), ''), nullif(btrim(new.organization_number), ''));
  elsif new.org_number is distinct from old.org_number then
    new.org_number := nullif(btrim(new.org_number), '');
  elsif new.organization_number is distinct from old.organization_number then
    new.org_number := nullif(btrim(new.organization_number), '');
  end if;

  new.organization_number := new.org_number;
  return new;
end
$function$

