CREATE OR REPLACE FUNCTION public.gridex_enforce_billing_underlay_price_area()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract_id uuid := coalesce(new.contract_id, new.customer_contract_id);
  v_contract_snapshot_id uuid;
  v_contract_area text;
  v_snapshot_area text;
  v_legacy_snapshot_area text;
  v_metadata_area text;
  v_canonical_area text;
begin
  if v_contract_id is null then
    return new;
  end if;

  select
    c.contract_price_snapshot_id,
    upper(nullif(btrim(c.price_area_used), '')),
    upper(nullif(btrim(c.price_snapshot #>> '{snapshot_json,price_area}'), '')),
    upper(nullif(btrim(c.metadata ->> 'selected_price_area'), ''))
  into
    v_contract_snapshot_id,
    v_contract_area,
    v_legacy_snapshot_area,
    v_metadata_area
  from public.customer_contracts c
  where c.id = v_contract_id
    and c.company_id = new.company_id;

  if not found then
    return new;
  end if;

  select upper(nullif(btrim(s.snapshot_json ->> 'price_area'), ''))
  into v_snapshot_area
  from public.contract_price_snapshots s
  where s.id = coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
    and s.contract_id = v_contract_id
    and s.company_id = new.company_id;

  v_canonical_area := coalesce(
    case when v_snapshot_area in ('SE1','SE2','SE3','SE4') then v_snapshot_area end,
    case when v_contract_area in ('SE1','SE2','SE3','SE4') then v_contract_area end,
    case when v_legacy_snapshot_area in ('SE1','SE2','SE3','SE4') then v_legacy_snapshot_area end,
    case when v_metadata_area in ('SE1','SE2','SE3','SE4') then v_metadata_area end
  );

  if coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id) is not null
     and v_canonical_area is null then
    raise exception 'billing_contract_price_area_missing'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  end if;

  if v_canonical_area is null then
    return new;
  end if;

  if new.price_area is null or nullif(btrim(new.price_area), '') is null then
    new.price_area := v_canonical_area;
  elsif upper(btrim(new.price_area)) <> v_canonical_area then
    raise exception 'billing_underlay_price_area_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'submitted_price_area', upper(btrim(new.price_area)),
              'canonical_price_area', v_canonical_area,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  else
    new.price_area := v_canonical_area;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_contract_availability_and_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  o public.contract_offers%rowtype;
  v_count bigint;
  v_statuses text[]:=array['draft','pending_signature','signed','active'];
begin
  if new.status not in ('draft','pending_signature','signed','active') then
    return new;
  end if;
  if new.contract_offer_id is null and new.contract_product_id is null and new.contract_product_version_id is null then
    return new;
  end if;

  select * into o
  from public.contract_offers
  where company_id=new.company_id and (
    id=new.contract_offer_id
    or (new.contract_product_version_id is not null and contract_product_version_id=new.contract_product_version_id)
    or (new.contract_product_id is not null and contract_product_id=new.contract_product_id and lifecycle_status='published')
  )
  order by version_number desc limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(o.version_series_id::text,0));
  if o.lifecycle_status<>'published' or not o.is_active
     or (o.valid_from is not null and o.valid_from>current_date)
     or (o.valid_to is not null and o.valid_to<current_date) then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;
  if not exists(
    select 1 from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    where ta.company_id=new.company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status='active'
      and ch.channel in ('internal','website','api','partner','phone') and ch.status='active'
      and (
        (ch.channel='internal' and ta.internal_sales_allowed)
        or (ch.channel='website' and ta.website_publication_allowed)
        or ch.channel in ('api','partner','phone')
      )
      and (ch.valid_from is null or ch.valid_from<=now())
      and (ch.valid_to is null or ch.valid_to>=now())
  ) then
    raise exception using errcode='23514',message='contract_channel_not_available';
  end if;

  if o.max_customers is not null then
    select count(*) into v_count
    from public.customer_contracts c
    where c.company_id=new.company_id and c.id is distinct from new.id
      and c.status=any(v_statuses) and (
        c.contract_offer_id=o.id
        or c.contract_product_id=o.contract_product_id
        or c.contract_product_version_id=o.contract_product_version_id
      );
    if v_count>=o.max_customers then
      raise exception using errcode='23514',message='contract_capacity_reached';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_contract_price_snapshot_hash_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_expected_hash text;
begin
  if new.snapshot_json is null then
    raise exception using
      errcode = '23502',
      message = 'contract_price_snapshot_json_required';
  end if;

  v_expected_hash := encode(
    extensions.digest(convert_to(new.snapshot_json::text, 'UTF8'), 'sha256'),
    'hex'
  );

  if nullif(btrim(coalesce(new.snapshot_hash, '')), '') is not null
     and lower(btrim(new.snapshot_hash)) is distinct from v_expected_hash then
    raise exception using
      errcode = '23514',
      message = 'contract_price_snapshot_hash_mismatch';
  end if;

  new.snapshot_hash := v_expected_hash;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_customer_contract_chain_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;
  v_contract_id uuid:=coalesce(
    nullif(v_row->>'customer_contract_id','')::uuid,
    nullif(v_row->>'contract_id','')::uuid
  );
  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;
  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;
  v_export_item_id uuid:=coalesce(
    nullif(v_row->>'invoice_export_item_id','')::uuid,
    nullif(v_row->>'canonical_export_item_id','')::uuid
  );
begin
  if v_company_id is null or v_customer_id is null then
    raise exception using errcode='23502',message='customer_chain_company_customer_required';
  end if;
  if v_contract_id is not null and not exists(
    select 1 from public.customer_contracts cc
    where cc.id=v_contract_id
      and cc.company_id=v_company_id
      and cc.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_contract_mismatch';
  end if;
  if v_metering_point_id is not null and not exists(
    select 1 from public.metering_points mp
    where mp.id=v_metering_point_id
      and mp.company_id=v_company_id
      and mp.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';
  end if;
  if v_underlay_id is not null and not exists(
    select 1 from public.billing_underlays bu
    where bu.id=v_underlay_id
      and bu.company_id=v_company_id
      and bu.customer_id=v_customer_id
      and (
        v_contract_id is null
        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';
  end if;
  if v_export_item_id is not null and not exists(
    select 1 from public.invoice_export_items iei
    where iei.id=v_export_item_id
      and iei.company_id=v_company_id
      and iei.customer_id=v_customer_id
      and (
        v_contract_id is null
        or iei.customer_contract_id=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_quote_binding_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_quote public.website_contract_quotes%rowtype;
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_quote_reference text:=nullif(v_row->>'quote_reference','');
  v_text text;
begin
  if v_quote_reference is null then return new; end if;

  select * into v_quote
  from public.website_contract_quotes q
  where q.company_id=v_company_id
    and q.quote_reference=v_quote_reference;
  if not found then
    raise exception using errcode='23503',message='quote_binding_not_found_for_tenant';
  end if;

  foreach v_text in array array[
    nullif(v_row->>'contract_product_id',''),
    nullif(v_row->>'contract_product_version_id',''),
    nullif(v_row->>'contract_publication_version_id',''),
    nullif(v_row->>'price_plan_id',''),
    nullif(v_row->>'price_plan_version_id',''),
    nullif(v_row->>'price_book_id',''),
    nullif(v_row->>'legal_bundle_version_id',''),
    nullif(v_row->>'energy_direction','')
  ] loop
    if v_text is null then
      raise exception using errcode='23502',message='quote_binding_target_identity_incomplete';
    end if;
  end loop;

  if v_quote.contract_product_id is distinct from (v_row->>'contract_product_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_product_mismatch';
  end if;
  if v_quote.contract_product_version_id is distinct from (v_row->>'contract_product_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_version_mismatch';
  end if;
  if v_quote.contract_publication_version_id is distinct from (v_row->>'contract_publication_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_publication_version_mismatch';
  end if;
  if v_quote.price_plan_id is distinct from (v_row->>'price_plan_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_mismatch';
  end if;
  if v_quote.price_plan_version_id is distinct from (v_row->>'price_plan_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_version_mismatch';
  end if;
  if v_quote.price_book_id is distinct from (v_row->>'price_book_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_book_mismatch';
  end if;
  if v_quote.legal_bundle_version_id is distinct from (v_row->>'legal_bundle_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_legal_bundle_mismatch';
  end if;
  if v_quote.energy_direction is distinct from (v_row->>'energy_direction') then
    raise exception using errcode='23514',message='quote_binding_energy_direction_mismatch';
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_fill_contract_price_snapshot_binding_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract public.customer_contracts%rowtype; v_site_area text; v_meter_area text; v_area text; v_snapshot_area text; v_snapshot_ppv uuid;
begin
  select * into v_contract from public.customer_contracts c where c.id=new.contract_id and c.company_id=new.company_id;
  if not found then return new; end if;
  if v_contract.customer_site_id is not null or v_contract.site_id is not null then
    select upper(nullif(btrim(s.price_area_code),'')) into v_site_area from public.customer_sites s where s.id=coalesce(v_contract.customer_site_id,v_contract.site_id) and s.company_id=new.company_id limit 1;
  end if;
  if v_contract.metering_point_id is not null then
    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')) into v_meter_area from public.metering_points m where m.id=v_contract.metering_point_id and m.company_id=new.company_id limit 1;
  end if;
  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then raise exception using errcode='23514',message='contract_snapshot_price_area_source_conflict'; end if;
  v_area:=coalesce(case when upper(nullif(btrim(v_contract.price_area_used),'')) in ('SE1','SE2','SE3','SE4') then upper(btrim(v_contract.price_area_used)) end,case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);
  v_snapshot_area:=upper(nullif(btrim(new.snapshot_json->>'price_area'),''));
  if v_snapshot_area is not null and v_snapshot_area not in ('SE1','SE2','SE3','SE4') then raise exception using errcode='23514',message='contract_snapshot_price_area_invalid'; end if;
  if v_snapshot_area is not null and v_area is not null and v_snapshot_area<>v_area then raise exception using errcode='23514',message='contract_snapshot_price_area_mismatch'; end if;
  v_snapshot_ppv:=nullif(new.snapshot_json->>'price_plan_version_id','')::uuid;
  if v_snapshot_ppv is not null and v_contract.price_plan_version_id is not null and v_snapshot_ppv<>v_contract.price_plan_version_id then raise exception using errcode='23514',message='contract_snapshot_price_plan_version_mismatch'; end if;
  new.price_plan_id:=coalesce(new.price_plan_id,v_contract.price_plan_id);
  new.price_plan_version_id:=coalesce(new.price_plan_version_id,v_contract.price_plan_version_id);
  new.price_book_id:=coalesce(new.price_book_id,v_contract.price_book_id);
  if coalesce(jsonb_array_length(new.base_price_components_snapshot),0)=0 then new.base_price_components_snapshot:=coalesce(v_contract.commercial_snapshot->'base_price_components_snapshot',v_contract.commercial_snapshot->'base_components','[]'::jsonb); end if;
  if coalesce(jsonb_array_length(new.price_components_snapshot),0)=0 then new.price_components_snapshot:=coalesce(v_contract.commercial_snapshot->'price_components_snapshot',v_contract.commercial_snapshot->'price_components','[]'::jsonb); end if;
  new.snapshot_json:=coalesce(new.snapshot_json,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object('price_area',coalesce(v_snapshot_area,v_area),'price_plan_id',new.price_plan_id,'price_plan_version_id',new.price_plan_version_id,'price_book_id',new.price_book_id,'contract_product_version_id',v_contract.contract_product_version_id,'contract_publication_version_id',v_contract.contract_publication_version_id,'legal_bundle_version_id',v_contract.legal_bundle_version_id,'base_price_components_snapshot',new.base_price_components_snapshot,'price_components_snapshot',new.price_components_snapshot));
  new.snapshot_schema_version:=coalesce(new.snapshot_schema_version,'gridex_contract_pricing_v8_area_bound');
  new.snapshot_hash:=null;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.gridex_fill_customer_contract_price_area_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_site_area text; v_meter_area text; v_site_grid text; v_meter_grid text; v_area text; v_grid text;
begin
  if new.customer_site_id is not null or new.site_id is not null then
    select upper(nullif(btrim(s.price_area_code),'')), upper(nullif(btrim(s.grid_area_code),'')) into v_site_area,v_site_grid
    from public.customer_sites s where s.id=coalesce(new.customer_site_id,new.site_id) and s.company_id=new.company_id limit 1;
  end if;
  if new.metering_point_id is not null then
    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')), upper(nullif(btrim(m.grid_area_code),'')) into v_meter_area,v_meter_grid
    from public.metering_points m where m.id=new.metering_point_id and m.company_id=new.company_id limit 1;
  end if;
  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then
    raise exception using errcode='23514',message='contract_price_area_source_conflict';
  end if;
  v_area:=coalesce(case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);
  v_grid:=coalesce(v_meter_grid,v_site_grid);
  if nullif(btrim(coalesce(new.price_area_used,'')),'') is null then new.price_area_used:=v_area;
  elsif v_area is not null and upper(btrim(new.price_area_used))<>v_area then raise exception using errcode='23514',message='contract_price_area_binding_mismatch';
  else new.price_area_used:=upper(btrim(new.price_area_used)); end if;
  if nullif(btrim(coalesce(new.grid_area_code_used,'')),'') is null then new.grid_area_code_used:=v_grid;
  elsif v_grid is not null and upper(btrim(new.grid_area_code_used))<>v_grid then raise exception using errcode='23514',message='contract_grid_area_binding_mismatch';
  else new.grid_area_code_used:=upper(btrim(new.grid_area_code_used)); end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.gridex_invalidate_site_operations_on_address_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_hash text := nullif(btrim(old.address_hash), '');
  v_new_hash text := nullif(btrim(new.address_hash), '');
  v_old_raw_fingerprint text;
  v_new_raw_fingerprint text;
  v_address_changed boolean;
begin
  v_old_raw_fingerprint := lower(concat_ws('|',
    nullif(btrim(old.street), ''),
    regexp_replace(coalesce(old.postal_code, ''), '\D', '', 'g'),
    nullif(btrim(old.city), ''),
    nullif(btrim(old.country), '')
  ));
  v_new_raw_fingerprint := lower(concat_ws('|',
    nullif(btrim(new.street), ''),
    regexp_replace(coalesce(new.postal_code, ''), '\D', '', 'g'),
    nullif(btrim(new.city), ''),
    nullif(btrim(new.country), '')
  ));

  if v_old_hash is null and v_new_hash is not null then
    v_address_changed := v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  elsif v_old_hash is not null and v_new_hash is not null then
    v_address_changed :=
      v_old_hash is distinct from v_new_hash
      or v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  else
    v_address_changed :=
      v_old_hash is distinct from v_new_hash
      or v_old_raw_fingerprint is distinct from v_new_raw_fingerprint;
  end if;

  if v_address_changed then
    update public.customer_operation_jobs
       set status = 'needs_review',
           stale_reason = 'site_address_changed_after_operation_started',
           locked_at = null,
           locked_by = null,
           lock_token = null,
           completed_at = now(),
           updated_at = now()
     where company_id = new.company_id
       and customer_site_id = new.id
       and status in ('queued', 'running', 'waiting_response');

    update public.customer_operation_request_snapshots
       set superseded_at = now()
     where company_id = new.company_id
       and customer_site_id = new.id
       and superseded_at is null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_is_current_session_allowed()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_status text;
  v_disabled_at timestamptz;
begin
  if v_user_id is null then
    return false;
  end if;
  if to_regclass('public.user_profiles') is null then
    return true;
  end if;
  if exists(
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'user_profiles'
      and column_name = 'disabled_at'
  ) then
    execute
      'select profile.user_status,profile.disabled_at
       from public.user_profiles profile where profile.id=$1'
    into v_status, v_disabled_at
    using v_user_id;
  else
    select profile.user_status
    into v_status
    from public.user_profiles profile
    where profile.id = v_user_id;
  end if;
  if coalesce(v_status, 'active') in (
    'disabled',
    'locked_security',
    'removed_from_company',
    'invitation_revoked'
  ) then
    return false;
  end if;
  return v_disabled_at is null;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_lock_customer_contract_tenant_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare v_profile jsonb; v_company jsonb; v_email jsonb; v_snapshot jsonb;
begin
  if tg_op='UPDATE' and (old.signed_at is not null or old.locked_at is not null or old.status in('signed','active','terminated','cancelled','expired'))
     and old.tenant_communication_snapshot<>'{}'::jsonb then
    new.tenant_communication_snapshot:=old.tenant_communication_snapshot;
    new.tenant_communication_snapshot_sha256:=old.tenant_communication_snapshot_sha256;
    new.tenant_legal_party_snapshot:=old.tenant_legal_party_snapshot;
    return new;
  end if;
  if new.company_id is null then return new; end if;
  select to_jsonb(t) into v_profile from public.tenant_legal_profiles t where t.company_id=new.company_id;
  select to_jsonb(c) into v_company from public.companies c where c.id=new.company_id;
  select to_jsonb(e) into v_email from public.company_email_settings e where e.company_id=new.company_id;
  new.tenant_legal_party_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'postal_address',v_profile->'postal_address','customer_service_email',v_profile->>'customer_service_email',
    'phone',v_profile->>'phone','website',v_profile->>'website','tenant_legal_profile_sha256',encode(digest(coalesce(v_profile,'{}')::text,'sha256'),'hex')
  ));
  v_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'snapshot_version','gridex_tenant_communication_v1',
    'company_id',new.company_id,'legal_name',coalesce(v_profile->>'legal_name',v_company->>'name'),
    'organization_number',coalesce(v_profile->>'organization_number',v_company->>'org_number'),
    'brand_name',coalesce(v_company#>>'{branding,brand_name}',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_name',coalesce(v_email->>'sender_name',v_company#>>'{branding,display_name}',v_company->>'name'),
    'sender_email',v_email->>'sender_email','reply_to',coalesce(v_email->>'reply_to_email',v_email->>'support_email',v_profile->>'customer_service_email'),
    'support_email',coalesce(v_email->>'support_email',v_profile->>'customer_service_email'),
    'logo_url',coalesce(v_company#>>'{branding,logo_url}',v_company->>'logo_url'),
    'brand_colors',coalesce(v_company#>'{branding,colors}','{}'::jsonb),
    'legal_footer',coalesce(v_company#>>'{branding,legal_footer}',v_email->>'legal_footer'),
    'phone',coalesce(v_profile->>'phone',v_company->>'phone'),
    'website',coalesce(v_profile->>'website',v_company->>'website'),
    'contract_publication_version_id',new.contract_publication_version_id,
    'price_plan_version_id',new.price_plan_version_id,'legal_bundle_version_id',new.legal_bundle_version_id,
    'locked_at',coalesce(new.signed_at,new.created_at,now())
  ));
  new.tenant_communication_snapshot:=v_snapshot;
  new.tenant_communication_snapshot_sha256:=encode(digest(v_snapshot::text,'sha256'),'hex');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_lock_signed_customer_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_old jsonb := to_jsonb(old);
  v_new jsonb := to_jsonb(new);
  v_immutable_keys text[] := array[
    'company_id','customer_id','contract_name','contract_type',
    'energy_direction','site_id','customer_site_id','metering_point_id',
    'contract_offer_id','public_contract_offer_id','offer_reference',
    'quote_reference','contract_product_id','contract_product_version_id',
    'contract_publication_version_id','price_plan_id',
    'price_plan_version_id','price_book_id','legal_bundle_version_id',
    'contract_price_snapshot_id','commercial_snapshot','legal_snapshot',
    'legal_versions_snapshot','tenant_communication_snapshot',
    'tenant_communication_snapshot_sha256','tenant_legal_party_snapshot',
    'signature_snapshot','signature_snapshot_sha256',
    'price_snapshot','campaign_snapshot','fixed_price_ore_per_kwh',
    'spot_markup_ore_per_kwh','variable_fee_ore_per_kwh',
    'markup_ore_per_kwh','monthly_fee_sek','invoice_fee_sek',
    'discount_value','discount_unit','start_fee_sek','admin_fee_sek',
    'break_fee_sek','vat_rate','green_fee_mode','green_fee_value',
    'binding_months','notice_months','optional_fee_lines','starts_at',
    'expected_start_at','ends_at','auto_renew_enabled',
    'auto_renew_term_months','terms_version','terms_signed_version',
    'signed_version','signed_at','signed_ip_hash','signed_user_agent'
  ];
  v_key text;
begin
  if tg_op='DELETE' then
    if old.status in ('signed','active','terminated','cancelled','expired')
       or old.signed_at is not null or old.locked_at is not null then
      raise exception using errcode='55000',message='signed_customer_contract_delete_forbidden';
    end if;
    return old;
  end if;

  if old.status in ('signed','active','terminated','cancelled','expired')
     or old.signed_at is not null or old.locked_at is not null then
    foreach v_key in array v_immutable_keys loop
      if v_new->v_key is distinct from v_old->v_key then
        raise exception using errcode='55000',message='signed_customer_contract_immutable:'||v_key;
      end if;
    end loop;

    if new.document_sha256 is distinct from old.document_sha256 then
      if old.document_sha256 is not null
         or coalesce(new.document_sha256,'') !~ '^[0-9a-f]{64}$'
         or not exists(
           select 1 from public.customer_contract_documents d
           where d.company_id=old.company_id
             and d.customer_contract_id=old.id
             and d.document_type='signed_contract_pdf'
             and d.document_sha256=new.document_sha256
             and d.verified_at is not null
         ) then
        raise exception using errcode='55000',message='signed_customer_contract_document_hash_binding_invalid';
      end if;
    end if;

    new.locked_at:=coalesce(old.locked_at,old.signed_at,now());
  elsif new.signed_at is not null or new.status in ('signed','active') then
    new.locked_at:=coalesce(new.locked_at,new.signed_at,now());
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_metering_points_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_company_id uuid;
begin
  if new.customer_id is not null and to_regclass('public.customers') is not null then
    select company_id into parent_company_id from public.customers where id = new.customer_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_id');
  end if;

  if new.site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'site_id');
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_normalize_audit_context_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_headers jsonb:='{}'::jsonb;
  v_raw_headers text:=nullif(current_setting('request.headers',true),'');
begin
  if v_raw_headers is not null then
    begin
      v_headers:=v_raw_headers::jsonb;
    exception when others then
      v_headers:='{}'::jsonb;
    end;
  end if;

  new.actor_type:=coalesce(
    nullif(new.actor_type,''),
    case when new.actor_user_id is null then 'system' else 'user' end
  );
  if new.actor_user_id is null then
    new.system_actor:=coalesce(
      nullif(new.system_actor,''),
      nullif(new.metadata->>'system_actor',''),
      'unspecified_system_actor'
    );
  else
    new.system_actor:=null;
  end if;

  new.request_id:=coalesce(
    nullif(new.request_id,''),
    nullif(new.metadata->>'request_id',''),
    nullif(v_headers->>'x-request-id',''),
    gen_random_uuid()::text
  );
  new.correlation_id:=coalesce(
    nullif(new.correlation_id,''),
    nullif(new.metadata->>'correlation_id',''),
    nullif(v_headers->>'x-correlation-id',''),
    new.request_id
  );
  new.resource_type:=coalesce(nullif(new.resource_type,''),new.entity_type);
  new.resource_id:=coalesce(nullif(new.resource_id,''),new.entity_id);
  new.previous_status:=coalesce(
    nullif(new.previous_status,''),
    nullif(new.old_values->>'lifecycle_status',''),
    nullif(new.old_values->>'status','')
  );
  new.new_status:=coalesce(
    nullif(new.new_status,''),
    nullif(new.new_values->>'lifecycle_status',''),
    nullif(new.new_values->>'status','')
  );
  new.metadata:=coalesce(new.metadata,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'actor_type',new.actor_type,
    'system_actor',new.system_actor,
    'request_id',new.request_id,
    'correlation_id',new.correlation_id,
    'resource_type',new.resource_type,
    'resource_id',new.resource_id,
    'previous_status',new.previous_status,
    'new_status',new.new_status
  ));
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_normalize_contract_price_snapshot_row_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_normalized jsonb;
begin
  if new.snapshot_json is not null then
    v_normalized := private.gridex_normalize_fixed_area_snapshot_v1(new.snapshot_json);
    new.snapshot_json := v_normalized;
    if v_normalized ? 'base_price_components_snapshot' then
      new.base_price_components_snapshot := v_normalized->'base_price_components_snapshot';
    end if;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_normalize_power_of_attorney_legal_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_candidate uuid;
  v_candidate_text text;
  v_document_company_id uuid;
  v_module_key text;
  v_locked_at timestamptz;
  v_linked_legacy_id uuid;
  v_legacy_exists boolean := false;
begin
  if new.legal_text_version_id is not null then
    select exists (
      select 1 from public.legal_text_versions legacy
      where legacy.id = new.legal_text_version_id
    ) into v_legacy_exists;
  end if;

  v_candidate := new.legal_bundle_version_document_id;

  -- Compatibility path for the website onboarding RPC that historically
  -- transported the canonical legal document id through legal_text_version_id.
  if v_candidate is null
     and new.legal_text_version_id is not null
     and not v_legacy_exists then
    v_candidate := new.legal_text_version_id;
    new.legal_text_version_id := null;
  end if;

  -- Other canonical writers already persist the immutable document id in their
  -- captured evidence/snapshot. Normalize those writes into the first-class
  -- column without changing their external behavior.
  if v_candidate is null then
    v_candidate_text := coalesce(
      nullif(new.evidence_payload->>'legal_bundle_version_document_id', ''),
      nullif(new.fullmakt_snapshot->>'legal_bundle_version_document_id', ''),
      nullif(new.metadata->>'legal_bundle_document_id', '')
    );
    if v_candidate_text is not null
       and v_candidate_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      v_candidate := v_candidate_text::uuid;
    end if;
  end if;

  if v_candidate is null then
    return new;
  end if;

  select lbv.company_id, d.module_key, lbv.locked_at, d.legacy_legal_text_version_id
    into v_document_company_id, v_module_key, v_locked_at, v_linked_legacy_id
    from public.legal_bundle_version_documents d
    join public.legal_bundle_versions lbv
      on lbv.id = d.legal_bundle_version_id
   where d.id = v_candidate;

  if not found then
    new.legal_bundle_version_document_id := v_candidate;
    return new; -- declarative FK returns the canonical 23503
  end if;

  if new.company_id is null or v_document_company_id is distinct from new.company_id then
    raise exception 'power_of_attorney_legal_document_tenant_mismatch' using errcode = '23514';
  end if;
  if v_module_key is distinct from 'power_of_attorney' then
    raise exception 'power_of_attorney_legal_document_type_mismatch' using errcode = '23514';
  end if;
  if v_locked_at is null then
    raise exception 'power_of_attorney_legal_document_not_locked' using errcode = '23514';
  end if;

  if new.legal_text_version_id is not null
     and v_linked_legacy_id is distinct from new.legal_text_version_id then
    raise exception 'power_of_attorney_legal_reference_mismatch' using errcode = '23514';
  end if;

  new.legal_bundle_version_document_id := v_candidate;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_partner_contract_event_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_event_type text;
  v_data jsonb;
begin
  if coalesce(new.metadata->>'source_channel','') <> 'partner_api' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_event_type := 'contract.created';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'offer_reference',new.offer_reference
    );
  elsif new.status is distinct from old.status then
    v_event_type := 'contract.status_changed';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'previous_status',old.status,
      'offer_reference',new.offer_reference
    );
  else
    return new;
  end if;

  perform private.gridex_emit_partner_resource_event_v2(
    new.company_id,
    new.customer_id,
    v_event_type,
    'contract',
    new.customer_contract_reference,
    v_data,
    'partner:' || v_event_type || ':' || new.id::text || ':' || coalesce(new.updated_at::text,new.created_at::text,now()::text)
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_powers_of_attorney_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_company_id uuid;
begin
  if new.customer_id is not null and to_regclass('public.customers') is not null then
    select company_id into parent_company_id from public.customers where id = new.customer_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_id');
  end if;
  if new.site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'site_id');
  end if;
  if new.metering_point_id is not null and to_regclass('public.metering_points') is not null then
    select company_id into parent_company_id from public.metering_points where id = new.metering_point_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'metering_point_id');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_protect_customer_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.customer_number is not null
     and btrim(old.customer_number) <> ''
     and new.customer_number is distinct from old.customer_number then
    raise exception using errcode = '23514', message = 'customer_number_is_permanent';
  end if;
  if (old.customer_number is null or btrim(old.customer_number) = '')
     and (new.customer_number is null or btrim(new.customer_number) = '')
     and new.customer_number is distinct from old.customer_number then
    -- normalize '' -> null noise writes without failing
    new.customer_number := old.customer_number;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_protect_signed_poa_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.signed_scope_snapshot is distinct from new.signed_scope_snapshot then
    raise exception 'Signed power-of-attorney scope snapshot is immutable.' using errcode = '55000';
  end if;
  if old.legal_snapshot_id is not null and old.legal_snapshot_id is distinct from new.legal_snapshot_id then
    raise exception 'Power-of-attorney legal snapshot link is immutable.' using errcode = '55000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id from public.contract_products cp where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id from public.legal_bundle_versions lb where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    else v_company_id := null;
  end case;
  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(v_company_id,'website',tg_table_name || '.' || lower(tg_op),v_entity_id);
    perform public.gridex_bump_contract_publication_revision(v_company_id,'api',tg_table_name || '.' || lower(tg_op),v_entity_id);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

