CREATE OR REPLACE FUNCTION public.sync_metering_points_identifiers()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  if (new.metering_point_id is null or btrim(new.metering_point_id) = '')
     and new.meter_point_id is not null
     and btrim(new.meter_point_id) <> '' then
    new.metering_point_id := new.meter_point_id;
  end if;

  if (new.meter_point_id is null or btrim(new.meter_point_id) = '')
     and new.metering_point_id is not null
     and btrim(new.metering_point_id) <> '' then
    new.meter_point_id := new.metering_point_id;
  end if;

  if new.metering_point_id is not null
     and btrim(new.metering_point_id) <> ''
     and (
       new.meter_point_id is null
       or btrim(new.meter_point_id) = ''
       or new.meter_point_id <> new.metering_point_id
     ) then
    new.meter_point_id := new.metering_point_id;
  elsif new.meter_point_id is not null
     and btrim(new.meter_point_id) <> ''
     and (
       new.metering_point_id is null
       or btrim(new.metering_point_id) = ''
       or new.metering_point_id <> new.meter_point_id
     ) then
    new.metering_point_id := new.meter_point_id;
  end if;

  return new;
end;
$function$
